from solution import fibfib
import multiprocessing

import pytest
from hypothesis import given, strategies as st


def ref(n: int) -> int:
    if n == 0:
        return 0
    if n == 1:
        return 0
    if n == 2:
        return 1
    a, b, c = 0, 0, 1
    for _ in range(3, n + 1):
        a, b, c = b, c, a + b + c
    return c


def _worker(conn, n):
    from solution import fibfib as f
    try:
        conn.send(f(n))
    except Exception as e:
        try:
            conn.send(e)
        except Exception:
            pass
    finally:
        try:
            conn.close()
        except Exception:
            pass


def run_with_timeout(n, timeout):
    parent, child = multiprocessing.Pipe(duplex=False)
    p = multiprocessing.Process(target=_worker, args=(child, n))
    p.start()
    child.close()
    p.join(timeout)
    if p.is_alive():
        p.terminate()
        p.join(timeout)
        return (False, None)
    try:
        if parent.poll(timeout):
            val = parent.recv()
        else:
            return (False, None)
    finally:
        try:
            parent.close()
        except Exception:
            pass
    if isinstance(val, Exception):
        raise val
    return (True, val)


def test_base_cases_zero():
    assert fibfib(0) == 0


def test_base_cases_one():
    assert fibfib(1) == 0


def test_base_cases_two():
    assert fibfib(2) == 1


def test_docstring_example_1():
    assert fibfib(1) == 0


def test_docstring_example_5():
    assert fibfib(5) == 4


def test_docstring_example_8():
    assert fibfib(8) == 24


def test_known_values_small():
    expected = [0, 0, 1, 1, 2, 4, 7, 13, 24, 44, 81, 149, 274]
    for n, v in enumerate(expected):
        assert fibfib(n) == v, f"n={n}"


@given(st.integers(min_value=3, max_value=12))
def test_recurrence_relation(n):
    assert fibfib(n) == fibfib(n - 1) + fibfib(n - 2) + fibfib(n - 3)


@given(st.integers(min_value=0, max_value=12))
def test_matches_reference_model(n):
    assert fibfib(n) == ref(n)


@given(st.integers(min_value=0, max_value=12))
def test_nonnegative(n):
    assert fibfib(n) >= 0


@given(st.integers(min_value=0, max_value=11))
def test_monotonic_nondecreasing(n):
    assert fibfib(n) <= fibfib(n + 1)


@given(st.integers(min_value=0, max_value=12))
def test_returns_int(n):
    v = fibfib(n)
    assert isinstance(v, int)


def test_efficiently_computes_large_n():
    # Spec requires efficient computation. Naive exponential recursion fails this.
    n = 30
    expected = ref(n)
    ok, val = run_with_timeout(n, timeout=1.5)
    assert ok, f"fibfib({n}) did not complete within time limit (inefficient?)"
    assert val == expected, f"fibfib({n}) == {val}, expected {expected}"
